class Policy:
    # Changed: Use UCB-style exploration that balances trying unknown tasks with exploiting known low scores,
    # and avoid re-picking solved tasks (score >= 1.0) unless no alternatives exist.
    def __init__(self):
        self.scores = {}
        self.picks = 0
        self.counts = {}

    def pick(self, keys, round_index):
        # Filter out solved tasks if we have alternatives
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if unsolved:
            keys = unsolved

        # UCB1-style: prefer tasks with high uncertainty (low count) or low score
        def ucb_value(k):
            if k not in self.scores:
                # Unknown task: high exploration bonus
                return float('inf') if self.counts.get(k, 0) == 0 else 1.0 / (self.counts[k] + 1)
            score = self.scores[k]
            count = self.counts.get(k, 0)
            # Exploitation term (lower score = higher priority) + exploration bonus
            return (1.0 - score) + math.sqrt(2 * math.log(self.picks + 1) / (count + 1))

        return max(keys, key=ucb_value)

    def record(self, task_id, score):
        self.scores[task_id] = score
        self.counts[task_id] = self.counts.get(task_id, 0) + 1
        self.picks += 1
